    int* buf = malloc((n > 0 ? n : 1) * sizeof(int));
    sortRange(a, buf, 0, n);
    free(buf);
}

code.python:
import random


def partition(a, lo, hi):
    p = random.randint(lo, hi)
    a[p], a[hi] = a[hi], a[p]
    pivot = a[hi]
    store = lo
    for i in range(lo, hi):
        if a[i] < pivot:
            a[i], a[store] = a[store], a[i]
            store += 1
    a[store], a[hi] = a[hi], a[store]
    return store


def quick_range(a, lo, hi):
    while lo < hi:
        p = partition(a, lo, hi)
        if p - lo < hi - p:
            quick_range(a, lo, p - 1)
            lo = p + 1
        else:
            quick_range(a, p + 1, hi)
            hi = p - 1


def quick_sort(a):
    quick_range(a, 0, len(a) - 1)
    return a

code.java:
static final Random RNG = new Random(7);

static void swap(int[] a, int i, int j) {
    int t = a[i]; a[i] = a[j]; a[j] = t;
}

static int partition(int[] a, int lo, int hi) {
    swap(a, lo + RNG.nextInt(hi - lo + 1), hi);
    int pivot = a[hi];
    int store = lo;
    for (int i = lo; i < hi; i++)
        if (a[i] < pivot) swap(a, i, store++);
    swap(a, store, hi);
    return store;
}

static void quickRange(int[] a, int lo, int hi) {
    while (lo < hi) {
        int p = partition(a, lo, hi);
        if (p - lo < hi - p) {
            quickRange(a, lo, p - 1);
            lo = p + 1;
        } else {
            quickRange(a, p + 1, hi);
            hi = p - 1;
        }
    }
}

static int[] quickSort(int[] a) {
    quickRange(a, 0, a.length - 1);
    return a;
}

